    try:
        response = await es.search(
            index=indices,
            body={
                "size": batch_size,
                "query": {
                    "bool": {
                        "must": [
                            {
                                "range": {
                                    "timestamp": {
                                        "gte": "now-1m",
                                        "lt": "now"
                                    }
                                }
                            },
                            {
                                "terms": {
                                    "agent_id": agent_ids
                                }
                            }
                        ]
                    }
                },
                "sort": [{"timestamp": "desc"}]
            }
