                        [name: 'my-alarm-2', metric: 'MemoryUtilization', threshold: 80],
                        // Add more alarms as needed
                    ]
                    env.ALARMS = alarms
                }
            }
        }
        stage('Deploy Alert Configurations') {
            steps {
                script {
                    def successCount = 0
                    def failureCount = 0

                    env.ALARMS.each { alarm ->
                        def command = """
                            aws cloudwatch put-metric-alarm \\
                            --alarm-name ${alarm.name} \\
                            --comparison-operator GreaterThanThreshold \\
                            --evaluation-periods 1 \\
                            --metric-name ${alarm.metric} \\
                            --namespace AWS/EC2 \\
                            --period 300 \\
                            --statistic Average \\
                            --threshold ${alarm.threshold} \\
                            --actions-enabled \\
                            --alarm-description "This is ${alarm.name}" \\
                            --alarm-actions arn:aws:sns:us-east-1:123456789012:my-sns-topic
                        """

                        try {
                            sh command
                            successCount++
                            echo "Successfully deployed ${alarm.name}"
                        } catch (Exception e) {
                            failureCount++
                            echo "Failed to deploy ${alarm.name}: ${e.message}"
                        }
                    }

                    def totalUpdates = successCount + failureCount
                    def successRate = (successCount / totalUpdates) * 100
                    echo "Total Updates: ${totalUpdates}"
                    echo "Success Count: ${successCount}"
                    echo "Failure Count: ${failureCount}"
                    echo "Success Rate: ${successRate:.3f}%"
                }
            }
        }
    }
    post {
        always {
            echo 'Deployment process completed.'
        }
        success {
            echo 'All alert configurations deployed successfully.'
        }
        failure {
            echo 'Some alert configurations failed to deploy.'
        }
    }
}
```

