from flask_caching import Cache
import redis
import hashlib

app = Flask(__name__)
cache = Cache(config={'CACHE_TYPE': 'redis', 'CACHE_REDIS_URL': 'redis://localhost:6379/0'})
cache.init_app(app)

@app.route('/api-docs')
@cache.cached(timeout=3600, key_prefix='api_docs')
def api_docs():
    # Generate or fetch Swagger documentation
    swagger_doc = {
        "openapi": "3.0.0",
        "info": {
            "title": "My API",
            "version": "1.0.0"
        },
        "paths": {
            "/agents": {
                "get": {
                    "summary": "Retrieve a list of agents.",
                    "responses": {
                        "200": {
                            "description": "Successful response"
                        }
                    }
                }
            }
        }
    }

    # Invalidate cache if content changes
    content_hash = hashlib.sha256(json.dumps(swagger_doc).encode()).hexdigest()
    if cache.get('content_hash') != content_hash:
        cache.set('content_hash', content_hash)
        cache.delete('api_docs')

    return make_response(jsonify(swagger_doc), 200)

if __name__ == '__main__':
    app.run(debug=False, threaded=True)
```

