```python
import json

class EndpointGrouper:
    def __init__(self, api_docs):
        self.api_docs = api_docs
        self.endpoints = self._load_api_docs()

    def _load_api_docs(self):
        try:
            return json.loads(self.api_docs)['endpoints']
        except (json.JSONDecodeError, KeyError) as e:
            raise ValueError(f"Invalid API docs: {e}")

    def group_endpoints(self):
        grouped_endpoints = {}
        for endpoint in self.endpoints:
            functionality = endpoint["functionality"]
            url = endpoint["url"]

            # Split nested functionalities into a list
            functionality_parts = functionality.split('.')
            current_group = grouped_endpoints

            # Traverse or create nested dictionaries
            for part in functionality_parts[:-1]:
                if part not in current_group:
                    current_group[part] = {}
                current_group = current_group[part]

            # Append the endpoint URL to the final nested group
            if functionality_parts[-1] not in current_group:
                current_group[_functionality_parts[-1]] = []
            current_group[functionality_parts[-1]].append(url)

        return grouped_endpoints

    def pretty_print(self, grouped_endpoints, indent=0):
        for key, value in grouped_endpoints.items():
            print(' ' * indent + f"{key}:")
            if isinstance(value, dict):
                self.pretty_print(value, indent + 2)
            else:
                print(' ' * (indent +  2) + f"- {value}")

