        {"functionality": "user.management", "url": "/users/{id}"},
        {"functionality": "product.management", "url": "/products"},
        {"functionality": "product.details", "url": "/products/{id}"}
    ]
}
'''

grouper = EndpointGrouper(api_docs)
grouped_endpoints = grouper.group_endpoints()
