        // Export the processed clip
        var exportPath = outputFolder + "/" + file.name;
        clipItem.exportFile(ExportFormat.FFMPEG, new File(exportPath));
    }
}

// Call the function with the input folder
importAndProcessClips(inputFolder);
```

### 3. Use Plugins and Extensions
