    if "token" in TOKEN_CACHE:
        token_info = TOKEN_CACHE["token"]
        if time.time() - token_info["timestamp"] < TOKEN_EXPIRATION:
            return token_info["token"]
        else:
            logging.warning("Token has expired. Retrieving a new token.")
            TOKEN_CACHE.pop("token", None)

    auth_url = "https://example.com/auth"
    auth_response = requests.post(auth_url, data={"username": "your_username", "password": "your_password"})
    if auth_response.status_code == 200:
        token = auth_response.json().get("access_token")
        TOKEN_CACHE["token"] = {"token": token, "timestamp": time.time()}
        return token
    else:
        logging.error(f"Failed to retrieve token: {auth_response.text}")
        raise Exception(f"Failed to retrieve token: {auth_response.text}")

def create_ticket(agent_report):
