                        'MetricName': 'Latency'
                    },
                    'Period': 60,
                    'Stat': 'Average'
                }
            },
            {
                'Id': 'm3',
                'MetricStat': {
                    'Metric': {
                        'Namespace': 'Zendesk/Metrics',
                        'MetricName': 'ErrorRate'
                    },
                    'Period':  60,
                    'Stat': 'Average'
                }
            },
            {
                'Id': 'm4',
                'MetricStat': {
                    'Metric': {
                        'Namespace': 'Zendesk/Metrics',
                        'MetricName': 'Throughput'
                    },
                    'Period': 60,
                    'Stat': 'Average'
                }
            }
        ],
        StartTime=start_time,
        EndTime=end_time
    )

    # Extract the metric data
    metric_data = response['MetricDataResults']

    # Prepare the CSV data
    csv_data = [
        ['Timestamp', 'TicketsPerMinute', 'Latency', 'ErrorRate', 'Throughput']
    ]

