            metric_data[0]['Values'][i],
            metric_data[1]['Values'][i],
            metric_data[2]['Values'][i],
            metric_data[3]['Values'][i]
        ]
        csv_data.append(row)

    # Write the CSV data to a file
    filename = f"metrics_{end_time.strftime('%Y%m%d%H%M%S')}.csv"
    with open(f"/tmp/{filename}", 'w', newline='') as csvfile:
