import logging
import logging.handlers
from datetime import datetime
import smtplib
from email.mime.text import MIMEText

# Create a logger
logger = logging.getLogger(__name__)
logger.setLevel(logging.DEBUG)

# Create a rotating file handler
handler = logging.handlers.RotatingFileHandler(
    'audit.log', maxBytes=1024*1024*5, backupCount=5
)
handler.setLevel(logging.DEBUG)

# Create a formatter and add it to the handler
formatter = logging.Formatter(
    '%(asctime)s - %(name)s - %(levelname)s - %(message)s - %(user)s'
)
handler.setFormatter(formatter)

# Add the handler to the logger
logger.addHandler(handler)

# Custom logging method to include user information
def log_with_user(level, message, user):
    record = logger.makeRecord(logger.name, level, '', 0, message, None, None, extra={'user': user})
    logger.handle(record)

# Example usage
