log_with_user(logging.DEBUG, 'This is a debug message', user)
log_with_user(logging.INFO, 'This is an info message', user)
log_with_user(logging.WARNING, 'This is a warning message', user)
log_with_user(logging.ERROR, 'This is an error message', user)
log_with_user(logging.CRITICAL, 'This is a critical message', user)

# Function to send email alerts
def send_email_alert(subject, body, to_emails):
    from_email = 'your-email@example.com'
    password = 'your-email-password'

    msg = MIMEText(body)
    msg['Subject'] = subject
    msg['From'] = from_email
    msg['To'] = ', '.join(to_emails)

    with smtplib.SMTP_SSL('smtp.example.com', 465) as server:
        server.login(from_email, password)
        server.sendmail(from_email, to_emails, msg.as_string())

# Check logs for critical issues and send alerts
def check_logs_for_critical_issues(log_file):
    with open(log_file, 'r') as file:
        lines = file.readlines()
        critical_lines = [line for line in lines if 'CRITICAL' in line]
        if critical_lines:
            subject = 'Critical Issues Detected in Logs'
            body = ''.join(critical_lines)
            to_emails = ['alert@example.com']
            send_email_alert(subject, body, to_emails)

check_logs_for_critical_issues('audit.log')
```

### Explanation

1. **Logging Configuration:**
   - The logging configuration remains the same as before, capturing logs at different levels.

2. **Email Alert Function:**
