                script {
                    // Analyze logs for errors or warnings
                    def logContent = readFile 'audit.log'
                    if (logContent.contains('ERROR') || logContent.contains('CRITICAL')) {
                        error 'Errors or critical issues found in logs.'
                    }
                }
            }
        }

        stage('Send Alerts') {
            steps {
                script {
                    // Send email alerts if critical issues are found
                    sh 'python check_logs_for_critical_issues.py'
                }
            }
        }

        stage('Archive Artifacts') {
            steps {
                archiveArtifacts artifacts: 'audit.log', fingerprint: true
            }
        }
    }

    post {
        always {
            // Send email with build status and logs
            mail to: 'team@example.com',
