#### Example Python Script (`generate_reports.py`):

```python
import pandas as pd
import os
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.application import MIMEApplication

def fetch_data():
    # Fetch data from a source (e.g., a database or a file)
    # For demonstration, let's assume we're reading from a CSV file
    df = pd.read_csv('team_data.csv')
    return df

def generate_report(df, team_member):
    # Generate a report for a specific team member
    report_df = df[df['name'] == team_member]
    report_path = f'reports/{team_member}_report.csv'
    report_df.to_csv(report_path, index=False)
    return report_path

def send_email(to_address, report_path):
    # Send the report via email
    msg = MIMEMultipart()
    msg['From'] = 'reports@example.com'
    msg['To'] = to_address
    msg['Subject'] = 'Compliance Report'

    body = MIMEText('Please find attached your compliance report.')
    msg.attach(body)

    with open(report_path, "rb") as attachment:
        part = MIMEApplication(
            attachment.read(),
            _subtype=os.path.splitext(report_path)[1][1:]
        )
        part.add_header('Content-Disposition', 'attachment', filename=os.path.basename(report_path))
        msg.attach(part)

    server = smtplib.SMTP('smtp.example.com', 587)
    server.starttls()
    server.login('username', 'password')
    server.sendmail(msg['From'], [msg['To']], msg.as_string())
    server.quit()

def main():
    df = fetch_data()
    team_members = df['name'].unique()

    for member in team_members:
        report_path = generate_report(df, member)
        send_email(member + '@example.com', report_path)
        print(f'Report sent to {member}')

if __name__ == '__main__':
    main()
