#### 1. Define User Roles in Auth0

Ensure that your users have roles assigned in Auth0. For example, you might have roles like `admin`, `editor`, and `viewer`.

#### 2. Update Middleware to Check Roles

Update the middleware to check for specific roles before granting access to certain API endpoints.

```python
from flask import Flask, request, jsonify
from functools import wraps
from auth0.v3.authentication import GetToken
from auth0.v3.management import Auth0
import os
import jwt

app = Flask(__name__)

# Load environment variables
auth0_domain = os.getenv('AUTH0_DOMAIN')
auth0_client_id = os.getenv('AUTH0_CLIENT_ID')
auth0_client_secret = os.getenv('AUTH0_CLIENT_SECRET')
jwt_secret = os.getenv('JWT_SECRET')

# Obtain an access token
get_token = GetToken(auth0_domain)
token = get_token.client_credentials(
    auth0_client_id,
    auth0_client_secret,
    f'https://{auth0_domain}/api/v2/'
)

# Initialize Auth0 management API
auth0 = Auth0(auth0_domain, token['access_token'])

def requires_auth(required_roles=None):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            auth_header = request.headers.get('Authorization', '')
            if not auth_header:
                return jsonify({"error": "Authorization header missing"}), 401

            token = auth_header.split(' ')[1]
            try:
                # Validate token here (use appropriate library or service)
                # For example, you can use jwt.decode or similar method
                user_info = validate_token(token)

                # Check if the user has the required roles
                user_roles = user_info.get('app_metadata', {}).get('roles', [])
                if required_roles and not any(role in user_roles for role in required_roles):
                    return jsonify({"error": "Unauthorized"}), _403

            except Exception as e:
                return jsonify({"error": str(e)}), 401

            return f(*args, **kwargs)
        return decorated
    return decorator

def validate_token(token):
    # Decode the token using the JWT secret
    try:
        decoded_token = jwt.decode(token, jwt_secret, algorithms=['HS256'])
        return decoded_token
    except jwt.ExpiredSignatureError:
        return jsonify({"error": "Token has expired"}), 401
    except jwt.InvalidTokenError:
        return jsonify({"error": "Invalid token"}), 401

@app.route('/api/admin-feature', methods=['GET'])
@requires_auth(required_roles=['admin'])
